import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(
                new BufferedReader(new InputStreamReader(System.in), 1 << 16));

        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;

        // A rua escolhida é no sentido Norte-Sul; alargá-la exige desapropriar
        // todas as quadras de um dos seus lados ao longo de todo o seu
        // comprimento, ou seja, exatamente uma coluna inteira do quadriculado.
        // Portanto, a resposta é a coluna com menor soma de valores.
        long[] colSum = new long[m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                in.nextToken();
                colSum[j] += (long) in.nval;
            }
        }

        long best = Long.MAX_VALUE;
        for (int j = 0; j < m; j++) {
            if (colSum[j] < best) {
                best = colSum[j];
            }
        }

        System.out.println(best);
    }
}
